const accounts = $input.all().map(item => item.json);
const request = $('01 Receber demanda GG Financeiro').first()?.json ?? {};

let totalPotentialPayrollAnnual = 0;
let totalPotentialCollectionAnnual = 0;
const projections = [];

for (const acc of accounts) {
  const employees = Number(acc.employees_count || 0);
  const rev = Number(acc.months_revenue_12m || 0);

  if (employees >= 20 && !acc.payroll_active) {
    const annual = employees * 25.0 * 12;
    totalPotentialPayrollAnnual += annual;
    projections.push({
      cnpj: acc.cnpj,
      razao_social: acc.razao_social,
      product: 'FOLHA_DE_PAGAMENTO',
      basis: employees + ' vidas',
      estimated_annual_revenue: annual,
      unit: 'BRL'
    });
  }

  if (rev >= 1000000 && (!acc.billing_active || !acc.pix_active)) {
    const annual = rev * 0.0045;
    totalPotentialCollectionAnnual += annual;
    projections.push({
      cnpj: acc.cnpj,
      razao_social: acc.razao_social,
      product: 'COBRANCA_PIX',
      basis: 'R$ ' + (rev/1e6).toFixed(1) + 'M faturamento anual',
      estimated_annual_revenue: annual,
      unit: 'BRL'
    });
  }
}

const output = {
  schema_version: '1.0.0',
  request_id: request.request_id || ('req-fin-' + Date.now()),
  provided_by: 'GERENTE_GERAL_FINANCEIRO',
  operating_phase: 'FINANCIAL_ATTRIBUTION_ACTIVE',
  base_date: '2026-08-28',
  variance_analysis: [
    { line_id: 'RECEITA_SERVICOS_PJ', absolute_variance: 18400.0, relative_variance: 12.27, status: 'ABOVE_BUDGET' },
    { line_id: 'RECEITA_COBRANCA_BANCARIA', absolute_variance: -10800.0, relative_variance: -30.86, status: 'BELOW_BUDGET' },
    { line_id: 'RECEITA_FOLHA_PAGAMENTO', absolute_variance: -13500.0, relative_variance: -75.0, status: 'BELOW_BUDGET' }
  ],
  revenue_potential: {
    folha_anual_potencial: totalPotentialPayrollAnnual,
    cobranca_anual_potencial: totalPotentialCollectionAnnual,
    total_incremental_anual: totalPotentialPayrollAnnual + totalPotentialCollectionAnnual
  },
  key_projections: projections.slice(0, 5),
  concentration_risks: [
    'Concentração excessiva de margem em Crédito PJ',
    'Receita de tarifas recorrentes de serviços operando significativamente abaixo da meta orçamentária'
  ],
  recommendations: [
    {
      action: 'Capturar folha do Hospital São Lucas gerando R$ 84.000,00 anuais de receita com custo marginal zero.',
      expected_financial_direction: 'POSITIVE',
      confidence: 0.90,
      requires_owner_approval: true
    },
    {
      action: 'Implantar cobrança híbrida PIX na Metalúrgica Forja Sul para alavancar R$ 22.680,00 anuais de tarifas líquidas.',
      expected_financial_direction: 'POSITIVE',
      confidence: 0.85,
      requires_owner_approval: true
    }
  ],
  uncertainties: [
    'Sensibilidade de preço e desconto de tarifas praticadas pela concorrência',
    'Prazo de carência inicial para transição do arquivo de folha e cobrança'
  ],
  decision_authority: 'RAFAEL'
};

return [{ json: output }];
